function model(p) {
  // An illustrative story: one member's data moving into and through a customer data platform. Systems, timings and
  // names are made up for teaching. realMs = milliseconds after Maria's claim is denied at 09:00; start/dur = playback seconds.
  const nSrc = Math.max(2, Math.min(5, Math.round(p.sources))), streaming = Math.round(p.claimsFeed) === 1;
  const consent = Math.round(p.consent) === 1, sf = Math.round(p.names) === 1;
  const SOURCES = ['portal', 'crm', 'claims', 'marketing', 'callcenter'].slice(0, nSrc);
  const has = id => SOURCES.includes(id);
  const N = sf
    ? { portal: 'Experience Cloud portal', crm: 'Health Cloud', claims: 'Claims system (MuleSoft)', marketing: 'Marketing Cloud Engagement', callcenter: 'Service Cloud Voice',
        ingest: 'Data 360 data streams', harmonize: 'Data 360 data model (DMOs)', unify: 'Identity resolution (Unified Individual)', insight: 'Calculated insights and segments',
        agent: 'Agentforce service agent', journey: 'Marketing Cloud journey', profile: 'Unified profile' }
    : { portal: 'Member portal', crm: 'CRM', claims: 'Claims system', marketing: 'Marketing platform', callcenter: 'Contact centre',
        ingest: 'Ingestion (data streams)', harmonize: 'Canonical data model', unify: 'Identity resolution', insight: 'Insights and segments',
        agent: 'Service agent', journey: 'Marketing journey', profile: 'Unified profile' };
  const ROLE = {
    portal: 'Where Maria signs in and checks her claim. Every page view is an event the platform can ingest.',
    crm: 'Holds her member record, contact points and service cases. The system of record for who she is; its record was loaded into the platform before the story starts.',
    claims: 'Adjudicates claims. In this story it denied her knee-scan claim at 09:00. Its feed is ' + (streaming ? 'streaming: a record arrives seconds after the decision.' : 'a nightly batch: records arrive at 02:00 the next day.'),
    marketing: 'Sends emails and records what she opens and clicks. Syncs engagement hourly.',
    callcenter: 'Takes her call, transcribes it and scores the sentiment.',
    ingest: 'One data stream per source. Streaming sources land in seconds; batch sources land on their schedule.',
    harmonize: 'Maps every source\'s fields onto one shared model (individual, contact point, case, claim, engagement) so records from different systems can be joined.',
    unify: 'Matches records that describe the same person (email and phone here) into one unified profile with a source count.',
    insight: 'Calculates insights over the whole profile ("denied claim plus repeated status checks") and keeps segments of members who match.',
    agent: 'A service agent, human or AI, who sees the unified profile in the CRM and gets follow-up tasks from the segment.',
    journey: 'Sends the "how to appeal" guide. Only runs for members who have opted in to marketing.',
    profile: 'What the platform knows about Maria right now: one record per source that has arrived.'
  };
  const ICON = { portal: 'app-window', crm: 'contact', claims: 'file-text', marketing: 'mail', callcenter: 'headset',
    ingest: 'download', harmonize: 'table-properties', unify: 'user-check', insight: 'lightbulb', agent: 'bot', journey: 'send', profile: 'id-card' };
  const KIND = { portal: 'source', crm: 'source', claims: 'source', marketing: 'source', callcenter: 'source', ingest: 'stage', harmonize: 'stage', unify: 'stage', insight: 'stage', agent: 'target', journey: 'target', profile: 'profile' };
  const ids = ['portal', 'crm', 'claims', 'marketing', 'callcenter', 'ingest', 'harmonize', 'unify', 'insight', 'profile', 'agent', 'journey'];
  const systems = ids.map(id => ({ id, name: N[id], role: ROLE[id], icon: ICON[id], kind: KIND[id], connected: KIND[id] !== 'source' || has(id),
    feed: KIND[id] === 'source' ? (id === 'claims' ? (streaming ? 'streaming' : 'nightly batch') : id === 'marketing' ? 'hourly sync' : 'streaming') : null }));
  const st = Object.fromEntries(ids.map(id => [id, has(id) || KIND[id] !== 'source' ? 'idle' : 'off']));
  const prof = { sources: ['crm'], claim: null, visits: 0, call: null, caseOpen: false, engagement: null, email: false, phone: false };
  let insight = null, segment = false, calls = 0, t = 0, maria = 'home';
  const scenes = [], events = [];
  const scene = (title, caption) => scenes.push({ i: scenes.length, title, caption, start: +t.toFixed(2) });
  const add = (station, kind, realMs, dur, note, path, set, extra) => {
    extra = extra || {};
    Object.assign(st, set || {});
    if (extra.maria) maria = extra.maria;
    if (extra.src && !prof.sources.includes(extra.src)) prof.sources.push(extra.src);
    Object.assign(prof, extra.prof || {});
    if (extra.insight !== undefined) insight = extra.insight;
    if (extra.segment !== undefined) segment = extra.segment;
    if (extra.call) calls++;
    events.push({ i: events.length, scene: scenes.length - 1, station, kind, realMs, start: +t.toFixed(2), dur, note,
      path: path && path.length ? path : [station], fail: !!extra.fail,
      snap: { status: Object.assign({}, st), maria, calls, insight, segment, profile: JSON.parse(JSON.stringify(prof)) } });
    t += dur;
  };
  const MIN = 60000, H = 3600000, NEXT = 17 * H; // 02:00 the next day
  const into = src => [src, 'ingest', 'harmonize', 'unify', 'profile'];
  const agentSees = has('claims') && streaming;

  scene('A bad morning', 'At 09:00 the claims system denies Maria\'s claim for a knee scan. Five systems will hear about her day; the platform hears only from the ones connected to it.');
  add('claims', 'deny', 0, 2.0, 'The claims system denies Maria\'s knee-scan claim and sends her a letter. ' + (has('claims') ? (streaming ? 'Its stream sends the record to the platform within seconds.' : 'Its nightly batch will send the record at 02:00 tomorrow.') : 'It is not connected to the platform, so the platform will never hear about it.'), [], { claims: has('claims') ? 'new' : 'off' }, { maria: 'home' });
  if (has('claims') && streaming) {
    scene('Seconds later', 'The claim record lands in its data stream, is mapped onto the shared model as a Claim, and is matched to Maria\'s profile by her member number and email.');
    add('ingest', 'ingest', 20000, 1.5, 'The claim record lands in the claims data stream.', ['claims', 'ingest'], { ingest: 'busy' });
    add('harmonize', 'map', 25000, 1.5, 'Mapped to the shared model: a Claim with status Denied, linked to an Individual.', ['ingest', 'harmonize'], { harmonize: 'busy' });
    add('unify', 'match', 30000, 1.6, 'Matched to Maria\'s unified profile. Her profile now says: one denied claim.', ['harmonize', 'unify', 'profile'], { unify: 'busy', profile: 'new' }, { src: 'claims', prof: { claim: 'denied', email: true } });
  }
  scene('She checks, twice', 'Maria opens the portal to see what happened, then again half an hour later. Each visit is an event, and portal events stream in as they happen.');
  add('portal', 'visit', 5 * MIN, 1.6, '09:05: Maria logs in to the portal and opens her claim. "Denied." The page view streams to the platform.', [], { portal: 'new' }, { maria: 'portal' });
  add('unify', 'match', 5 * MIN + 10000, 1.4, 'Mapped as an Engagement event and matched to her profile: 1 visit.', into('portal'), { ingest: 'busy', harmonize: 'busy', unify: 'busy', profile: 'new' }, { src: 'portal', prof: { visits: 1, email: true } });
  add('portal', 'visit', 35 * MIN, 1.4, '09:35: she checks again. Nothing has changed.', [], { portal: 'new' }, { maria: 'portal' });
  add('unify', 'match', 35 * MIN + 10000, 1.4, 'Second visit matched. Her profile now says: 2 status checks in 30 minutes.', into('portal'), {}, { src: 'portal', prof: { visits: 2 } });
  if (has('claims') && streaming) {
    scene('The platform notices', 'A calculated insight runs over the whole profile: a denied claim plus two status checks within the hour. Maria is flagged as at risk, and the "members at risk" segment refreshes.');
    add('insight', 'insight', 36 * MIN, 2.0, 'Insight: denied claim + 2 status checks in an hour = "at risk of complaint". The segment picks her up.', ['profile', 'insight'], { insight: 'new' }, { insight: 'at-risk', segment: true });
    add('agent', 'task', 37 * MIN, 1.8, 'The segment activates to the CRM: a follow-up task for a service agent, and the unified profile is shown on her record.', ['insight', 'agent'], { agent: 'new' });
  }
  scene('The call', 'At 09:50 Maria calls the contact centre. What the agent can see decides how the call goes.');
  if (agentSees) {
    add('agent', 'call-good', 50 * MIN, 2.4, '09:50: Maria calls. The agent already sees the denied claim and her two visits on her unified profile, explains the denial and starts an appeal on the spot.', ['agent'], { agent: 'good' }, { maria: 'calling', call: true });
  } else {
    add('agent', 'call-bad', 50 * MIN, 2.4, '09:50: Maria calls. The agent sees no claim on her record' + (has('claims') ? ' yet (the batch arrives tonight)' : '') + ', asks her to read out the letter, and opens a case to investigate.', ['agent'], { agent: 'bad' }, { maria: 'calling', call: true, fail: true });
  }
  if (has('callcenter')) add('unify', 'match', 58 * MIN, 1.5, 'The call transcript and its sentiment (' + (agentSees ? 'neutral, resolved' : 'negative, unresolved') + ') stream in and are matched to her profile.', into('callcenter'), { callcenter: 'new' }, { src: 'callcenter', prof: { call: agentSees ? 'neutral' : 'negative', phone: true } });
  if (has('marketing')) {
    add('marketing', 'sync', 60 * MIN, 1.3, '10:00: the marketing platform\'s hourly sync brings her email engagement history.', [], { marketing: 'new' });
    add('unify', 'match', 60 * MIN + 20000, 1.3, 'Engagement history matched: her profile now has ' + (prof.sources.length + 1) + ' sources.', into('marketing'), {}, { src: 'marketing', prof: { engagement: 'opens the newsletter' } });
  }
  add('crm', 'case', 62 * MIN, 1.4, 'The CRM records a service case from the call' + (agentSees ? ' (appeal started).' : ' (investigate claim).'), [], { crm: 'new' });
  add('unify', 'match', 62 * MIN + 10000, 1.4, 'The case is mapped and matched: her profile now carries the open case.', into('crm'), {}, { src: 'crm', prof: { caseOpen: true, phone: true } });
  if (has('claims') && !streaming) {
    scene('02:00, the batch', 'Seventeen hours later the nightly claims batch lands. Only now does the platform learn that the claim was denied, and the insight fires in the middle of the night.');
    add('ingest', 'ingest', NEXT, 1.5, '02:00 next day: the nightly claims file lands in its data stream.', ['claims', 'ingest'], { ingest: 'busy' });
    add('unify', 'match', NEXT + 20000, 1.5, 'Mapped and matched: her profile finally says "denied claim".', ['ingest', 'harmonize', 'unify', 'profile'], { harmonize: 'busy', unify: 'busy', profile: 'new' }, { src: 'claims', prof: { claim: 'denied' } });
    add('insight', 'insight', NEXT + MIN, 1.8, 'Insight: denied claim + status checks + an unresolved call = "at risk". Seventeen hours late.', ['profile', 'insight'], { insight: 'new' }, { insight: 'at-risk', segment: true });
    add('agent', 'task', NEXT + 2 * MIN, 1.6, 'A follow-up task reaches the service agent for the morning.', ['insight', 'agent'], { agent: 'new' });
  }
  if (!has('claims')) {
    scene('Nothing to notice', 'Without the claims feed, the profile shows a member who visited the portal and called. The insight needs the denied claim, so it never fires and no segment picks her up.');
    add('insight', 'none', 3 * H, 2.0, 'The insight runs over her profile: visits and a call, but no claim. Nothing fires. Nothing activates.', ['profile', 'insight'], { insight: 'idle' }, { insight: null });
  }
  const insightMs = insight ? (streaming ? 36 * MIN : NEXT + MIN) : null;
  if (insight) {
    scene('Activation', 'The segment reaches two targets: a follow-up task for the service agent, and the "how to appeal" journey for members who have opted in to marketing.');
    const fuMs = streaming ? 90 * MIN : NEXT + 7 * H;
    add('agent', 'followup', fuMs, 2.0, (streaming ? '10:30' : '09:00 next day') + ': the service agent calls Maria back with the appeal status' + (streaming ? ', before she has to call again.' : '. By then she has called twice.'), ['agent'], { agent: 'good' }, { maria: 'home', prof: {}, call: !streaming });
    if (has('marketing') && consent) add('journey', 'email', fuMs + 30 * MIN, 1.8, 'The "how to appeal" email goes out: she is in the segment and opted in to marketing.', ['insight', 'journey'], { journey: 'good' });
    else if (has('marketing')) add('journey', 'blocked', fuMs + 30 * MIN, 1.8, 'The journey skips her: she opted out of marketing. Consent governs marketing, not the service follow-up she already got.', ['insight', 'journey'], { journey: 'blocked' });
    else add('journey', 'nosource', fuMs + 30 * MIN, 1.4, 'The marketing platform is not connected, so there is no journey to run.', [], { journey: 'off' });
  } else {
    add('agent', 'again', 2 * 24 * H, 2.0, 'Two days later Maria calls again about the same claim, and explains from the start. ' , ['agent'], { agent: 'bad' }, { maria: 'calling', call: true, fail: true });
  }
  const proactive = agentSees, followUpSameDay = !!insight && streaming;
  const marketingActivated = !!insight && has('marketing') && consent;
  const outcome = !insight
    ? 'The platform never saw the claim. Maria called ' + calls + ' times and explained herself each time. Nothing was flagged and nothing was activated.'
    : proactive
      ? 'One call, resolved. The denial, her two status checks and the call reached her profile within minutes, the agent saw all of it, and the follow-up came at 10:30' + (marketingActivated ? ', with the appeal guide by email at 11:00.' : '.')
      : 'The agent could not see the denial on the call. The platform learned about it at 02:00 and the follow-up came the next morning' + (marketingActivated ? ', with the appeal guide after it.' : '.') + ' Maria called ' + calls + ' times.';
  const soWhat = !has('claims') ? 'So what: a platform knows only what is connected to it. The insight that mattered needed the claims feed, and the best match rules cannot join data that never arrives.'
    : !streaming ? 'So what: a nightly batch makes the platform right about yesterday. For a same-day action the feed that carries the trigger has to stream.'
    : !consent && has('marketing') ? 'So what: consent decides where a segment may activate. Service outreach still happened; marketing did not, and that is the design working.'
    : 'So what: ingest, harmonise, unify, calculate, activate. Each stage is simple; the value is that the insight saw the whole member, and acted before she had to call again.';
  scene('So what', soWhat);
  add('maria', 'outcome', events[events.length - 1].realMs, 4.0, outcome, [], {}, { maria: 'home' });
  scenes.forEach((s, k) => { s.end = k < scenes.length - 1 ? scenes[k + 1].start : +t.toFixed(2); s.dur = +(s.end - s.start).toFixed(2); });
  const fin = events[events.length - 1].snap;
  return {
    sourcesConnected: SOURCES, names: sf ? 'salesforce' : 'generic', claimsFeed: streaming ? 'streaming' : 'batch', consent,
    systems, scenes, events, duration: +t.toFixed(2), markers: scenes.map(s => s.start),
    profile: fin.profile, insight, insightMs, segment, proactive, followUpSameDay, marketingActivated, calls,
    outcome, soWhat,
    summary: (streaming ? 'Streaming claims' : 'Nightly claims batch') + ', ' + nSrc + ' of 5 sources: ' + (proactive ? 'the agent saw the denial on the first call and the follow-up came the same day' : insight ? 'the insight fired at 02:00 and the follow-up came a day late' : 'the platform never saw the claim and nothing was activated') + (marketingActivated ? '; the appeal email went out.' : has('marketing') && insight ? '; no email, she opted out.' : '.')
  };
}

checkCode:
function check(p) {
  const m = model(p), n = Math.max(2, Math.min(5, Math.round(p.sources))), streaming = Math.round(p.claimsFeed) === 1, consent = Math.round(p.consent) === 1;
  const ordered = m.events.every((e, k) => !k || (e.realMs >= m.events[k - 1].realMs && e.start >= m.events[k - 1].start));
  const connected = m.sourcesConnected, arrived = m.profile.sources;
  const profileOk = arrived.length === n && connected.every(s => arrived.includes(s)) && arrived.every(s => connected.includes(s));
  const hasClaims = connected.includes('claims'), hasMkt = connected.includes('marketing');
  const insightOk = (m.insight === 'at-risk') === hasClaims && m.segment === hasClaims;
  const proactiveOk = m.proactive === (hasClaims && streaming) && m.followUpSameDay === (hasClaims && streaming);
  const mktOk = m.marketingActivated === (hasClaims && hasMkt && consent);
  const flip = model(Object.assign({}, p, { names: 1 - Math.round(p.names) }));
  const namesOnly = flip.insight === m.insight && flip.proactive === m.proactive && flip.marketingActivated === m.marketingActivated && flip.calls === m.calls && JSON.stringify(flip.profile) === JSON.stringify(m.profile);
  return {
    pass: ordered && profileOk && insightOk && proactiveOk && mktOk && namesOnly,
    detail: 'Profile built from ' + arrived.length + ' of ' + n + ' connected sources; the at-risk insight ' + (m.insight ? 'fired' : 'never fired') + (hasClaims ? '' : ' (no claims feed)') +
      '; the agent ' + (m.proactive ? 'saw the denial on the first call' : 'did not see the denial on the call') + '; marketing ' + (m.marketingActivated ? 'activated' : 'did not activate') +
      '; Maria called ' + m.calls + (m.calls === 1 ? ' time' : ' times') + '; ' + m.events.length + ' events in time order' + (ordered ? '' : ' (NOT)') + ' and switching names ' + (namesOnly ? 'changes nothing else.' : 'CHANGES the outcome.')
  };
}
